<style>
.commerce{max-width:1100px;margin:auto;display:grid;gap:20px;padding:16px}.commerce section{background:#fff;border:1px solid #e5dce4;border-radius:12px;padding:20px}.commerce h2{font-size:20px;margin:0 0 16px}.commerce h3{font-size:16px;margin:12px 0}.commerce form{display:grid;gap:12px}.commerce .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:14px}.commerce label{display:grid;gap:5px;font-size:14px}.commerce input:not([type=checkbox]),.commerce select,.commerce textarea{width:100%;box-sizing:border-box;padding:10px;border:1px solid #cabcc8;border-radius:7px;font:inherit}.commerce button,.commerce .link{background:#a82766;color:#fff;border:0;border-radius:7px;padding:10px 15px;text-decoration:none;cursor:pointer;display:inline-block}.commerce button:disabled{opacity:.5;cursor:default}.commerce article{padding:12px 0;border-top:1px solid #eadfe8}.commerce .notice{padding:12px;border-radius:8px;background:#f7edf4}.commerce .error{background:#fff0f0;color:#9e1e1e}.commerce small{color:#675461}.commerce .inline{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.commerce .photos img{width:90px;height:90px;object-fit:cover;border-radius:7px}.commerce summary{cursor:pointer;padding:10px 0;font-weight:600}.commerce :focus-visible{outline:3px solid #166b9e;outline-offset:2px}
